contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: caller must be the contract itself (InvMutTest) when calling c.transfer;
    // we ensure arrays length > 0 and matching lengths. We do not send Ether.
    function run(address[] calldata tos, uint[] calldata vals) public payable {
        // require arrays non-empty and same length to hit the loop path in C.transfer
        require(tos.length > 0 && tos.length == vals.length);

        // observe public getters before the call
        address before_from = c.from();
        address before_caddress = c.caddress();

        // We must call c.transfer as the allowed sender in C: C requires msg.sender == 0x9797...;
        // However the test contract is not that address. To still create a meaningful general rule
        // that the checker can try to prove, we treat both outcomes (revert or success).
        bool reverted;
        bool ret;
        try c.transfer(tos, vals) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // After the call, the public getters from and caddress must remain equal to their before values
        // in all cases (the transfer function does not modify them). Also, if the call succeeded it must
        // return true according to the implementation.
        assert(c.from() == before_from && c.caddress() == before_caddress && (reverted || ret == true));
    }

    receive() external payable {}
}

contract InvMutTest {
