    constructor(C _c) { c = _c; }

    // Single public test: call c.transfer and assert that it either reverts or returns true.
    function run(address[] calldata tos, uint[] calldata vals) public payable {
        // require non-empty and matching lengths to exercise the looping behavior in C.transfer
        require(tos.length > 0 && tos.length == vals.length);

        bool reverted;
        bool returnedFalse;
        try c.transfer(tos, vals) returns (bool r) {
            reverted = false;
            returnedFalse = (r == false);
        } catch {
            reverted = true;
            returnedFalse = false;
        }

        // General rule: the call either reverts OR it returns true (i.e., it cannot successfully return false).
        assert(reverted || !returnedFalse);
    }

    receive() external payable {}
}

