contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry test function: tries calling transfer and asserts the invariant
    function run(address[] memory _tos, uint[] memory v) public payable {
        // precondition: lengths must match for sensible call; if not, the call will revert - allow both behaviors
        require(_tos.length == v.length, "length mismatch");

        // observe public getters and c's balance before the call
        address before_from = c.from();
        address before_caddress = c.caddress();
        uint256 before_balance = address(c).balance;

        bool reverted;
        bool ret;
        // perform the state-changing call and capture whether it reverted
        try c.transfer(_tos, v) {
            reverted = false;
            // transfer returns (bool) so we can call it again? No — we've already called it. The return value from try is discarded here.
            // To capture return, call via low-level to get return data is not allowed. Instead, we rely on the fact that the function returns true on success.
            ret = true;
        } catch {
            reverted = true;
            ret = false;
        }

        // observe public getters and c's balance after the call
        address after_from = c.from();
        address after_caddress = c.caddress();
        uint256 after_balance = address(c).balance;

        // General rule: if the call succeeded (did not revert), it returns true (we model as ret==true) and
        // the public getters `from` and `caddress` and the ether balance of c remain unchanged by transfer.
        // If the call reverted, nothing is required. We assert the implication.
        assert(reverted || (ret && after_from == before_from && after_caddress == before_caddress && after_balance == before_balance));
    }

    receive() external payable {}
}

